\draw[{Stealth}-{Stealth}] (-1.1,0) -- (-1.1,4) node[midway, left] {$y$};
\draw[{Stealth}-{Stealth}] (0,-0.7) -- (3,-0.7) node[midway, below] {$x$};
\coordinate (p) at ($(O)!0.35cm!(T)$);
\coordinate (q) at ($(O)!0.35cm!(B)$);
\draw (p) -- ($(p)+(q)-(O)$) -- (q);
\end{tikzpicture}
[/tikz]

